import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, mul, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry: thin rule
  const geometry = new PlaneGeometry(2, 0.1, 64, 64);

  // Node material
  const material = new MeshStandardNodeMaterial();
  material.color = new Color(
    (config.intent?.visualSpec?.colors?.paper) ??
      '#e8ecf2'
  );

  // Texture nodes (values will be set asynchronously)
  const colorMapNode = texture();
  const depthMapNode = texture();

  // Assign nodes to material
  material.mapNode = colorMapNode;
  // Subtle displacement
  material.displacementNode = mul(depthMapNode, float(0.04));

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Async texture loading
  const loadedTextures = [];
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorMapNode.value = tex;
      loadedTextures.push(tex);
      material.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthMapNode.value = tex;
      loadedTextures.push(tex);
      material.needsUpdate = true;
    });
  }

  // Hover rise‑in animation (0.15 scene units)
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(
    mesh.position,
    { y: '+=0.15', duration: 0.7, ease: 'power3.out' }
  );

  // Click handler emits navigation event
  const onClick = () => {
    ctx.emit('hub-features.select', {});
  };

  // User‑data handlers
  root.userData.handlers = {
    hover: () => hoverTl.play(),
    hoverout: () => hoverTl.reverse(),
    click: onClick,
  };

  // Apply parallax primitive if available
  const primitiveRefs = [];
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    const prim = ctx.primitives['parallax-scroll'](mesh, {
      intensity: 0.15,
    });
    primitiveRefs.push(prim);
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    hoverTl.kill();
    primitiveRefs.forEach((p) => p.cleanup && p.cleanup());
    geometry.dispose();
    material.dispose();
    // Textures are cached; dispose if they were created uniquely
    loadedTextures.forEach((tex) => {
      if (tex && tex.dispose) tex.dispose();
    });
  };

  return root;
}
